scwin.vScrenID = "ULDINS16400.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : ETN 마스터  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }
    dts_detail.removeAll();
    $c.stf.setObjectValue(cmb_cb_p_group, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_1, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_2, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_3, "");
    $c.stf.setObjectValue(cmb_cb_p_attr_4, "");
    $c.stf.setObjectValue(rdo_BAS_IDX_CNTR_TP, "");
    $c.stf.setObjectValue(rdo_BAS_IDX_CLSS, "");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDSTKINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdetn.select.liststdcdetnInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.value + "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_YN) + "&{P}SISUDATE=" + edt_SISUDATE.getValue() + "&{P}EISUDATE=" + edt_EISUDATE.getValue() + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : etn 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    dts_detail.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ETN_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdetn.select.readstdcdetnInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};
scwin.clickRdoTp = function() {
    var BAS_IDX_CNTR_TP_CD = $c.stf.getObjectValue(rdo_BAS_IDX_CNTR_TP);
    if (BAS_IDX_CNTR_TP_CD != "99") {
        $c.stf.setObjectValue(txb_BAS_IDX_CNTR_TP_MISC, "");
        txb_BAS_IDX_CNTR_TP_MISC.setDisabled(true);
        txb_BAS_IDX_CNTR_TP_MISC.style.backgroundColor = '#b9d4f7';
    } else {
        txb_BAS_IDX_CNTR_TP_MISC.setDisabled(false);
        txb_BAS_IDX_CNTR_TP_MISC.style.backgroundColor = 'white';
    }
};
scwin.clickRdoClss = function() {
    var BAS_IDX_CLSS_CD = $c.stf.getObjectValue(rdo_BAS_IDX_CLSS);
    if (BAS_IDX_CLSS_CD != "99") {
        $c.stf.setObjectValue(txb_BAS_IDX_CLSS_MISC, "");
        txb_BAS_IDX_CLSS_MISC.setDisabled(true);
        txb_BAS_IDX_CLSS_MISC.style.backgroundColor = '#b9d4f7';
    } else {
        txb_BAS_IDX_CLSS_MISC.setDisabled(false);
        txb_BAS_IDX_CLSS_MISC.style.backgroundColor = 'white';
    }
};



/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
        txb_ISU_NM.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_BAS_IDX_CNTR_TP) == "99" && (txb_BAS_IDX_CNTR_TP_MISC.getValue().indexOf(" ") == "" || $c.stf.getObjectValue(txb_BAS_IDX_CNTR_TP_MISC) == "")) {
        $c.win.alert("기초지수국가구분이 기타일 경우에는 내용을 입력해 주시기 바랍니다.");
        txb_BAS_IDX_CNTR_TP_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_IDX_CNTR_TP_MISC, 40, "기초지수 국가 구분 기타")) {
        txb_BAS_IDX_CNTR_TP_MISC.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_BAS_IDX_CLSS) == "99" && (txb_BAS_IDX_CLSS_MISC.getValue().indexOf(" ") == "" || $c.stf.getObjectValue(txb_BAS_IDX_CLSS_MISC) == "")) {
        $c.win.alert("기초지수분류가 기타일 경우에는 내용을 입력해 주시기 바랍니다.");
        txb_BAS_IDX_CLSS_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_IDX_CLSS_MISC, 40, "기초지수분류 기타")) {
        txb_BAS_IDX_CLSS_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_MEMO_CONTN, 200, "담당자메모")) {
        txa_MEMO_CONTN.focus();
        return false;
    }

    //CFI체크
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
};




/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정 - 채권과 동일 .....
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "D";
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};



/********************************************** 
 * 함수명   : ins_modify
 * 설명       : etn 표준코드  수정한다.
 ***********************************************/
scwin.ins_modify = function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRUDSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_modify.Action = "/StdCdEtnInfoAction.do?method=modifyStdCdEtnInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInputMaster=dts_detail)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       : etn 삭제처리한다.
 ***********************************************/
scwin.ins_remove = function() {

    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_Delete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_remove.Action = "/StdCdEtnInfoAction.do?method=removeStdCdEtnInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_remove.KeyName = "toinb_dataid4";
    trs_remove.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_remove.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_remove.Post();
};



/*
 * 한글 입력불가
 */
scwin.fn_ChkHan = function(Obj) {
    var limit_char = /[ㄱ-ㅎ|ㅏ-ㅣ|가-힝]/g;
    var numstr = $c.stf.getObjectValue(Obj);
    if (limit_char.test(numstr)) {
        $c.win.alert("한글은 입력할 수 없습니다.");
        Obj.focus();
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.libRoundPanel.PanelToGroupBox(panel_2);

    //PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_4);
    //PanelToGroupBox(panel_6);

    ins_combo_set(dts_CURR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02475", "SEL"); //통화코드 
    ins_combo_set(dts_LIST_STAT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00714", "SEL"); //00714 - D:상장폐지I:미발행N:비상장Y:상장Z:기타 
    ins_combo_set(dts_STD_CD_APCT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03527"); //03527 - 신청자구분 
    ins_combo_set(dts_ETP_PROD_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03903", "SEL"); //ETP상품구분코드
    $c.cp.removeRow(dts_ETP_PROD_TP_CD, "1");
    $c.cp.removeRow(dts_ETP_PROD_TP_CD, "2");

    //cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "13", "D", "", "", "G");
    fn_CtrlBtn_temp("no_data");
    $c.stf.showObj(txb_DEL_RSN, false);
    $c.stf.showObj(txb_STD_CD_APPL_ID, false);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txa_REF_CONTN, false);

    //hidden패널
    $c.stf.showObj(panel_12, false);

    //최대수익액, 최대손실액, 발행가액 없앤다 2013.12.5
    $c.stf.showObj(edt_BND_ISU_PRC, false);

    //2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    $c.stf.showObj(btn_clearPwd, false);
    //2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    var arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (var i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.txb_pSTD_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pSTD_CD.value == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.cmb_pACTIV_YN_OnSelChange = function() {
    scwin.ins_search();
};
scwin.txb_pISU_KOR_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISU_KOR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.img_SISUDATE_onclick = function() {
    popUpCalendar2(edt_SISUDATE);
};
scwin.img_EISUDATE_onclick = function() {
    popUpCalendar2(edt_EISUDATE);
};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (row == 0) return;
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    scwin.ins_detail(STD_CD);
};
scwin.btn_file_onclick = function() {
    /*
    	txb_param1 에는 신청ID
    	txb_param2 에는 구분값을 넣는데.. 
         + "1 : 발행기관신청, 팩스-발행기관신청 \n"
    	 + "2 : 표준코드신청, 팩스-표준코드신청 \n"
    	 + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(txb_STD_CD_APPL_ID.getValue()); // 표준코드  신청 ID  
    txb_param2.setValue("2");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};
scwin.btn_modify_onclick = function() {
    if (scwin.fn_formCheck() == false) return;
    ins_popupOpen(txb_DEL_RSN, "", "ULDINS93900", "수정사유", "470", "190");
};
scwin.btn_delete_onclick = function() {
    txb_param1.setValue("");
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    // 삭제 신청건수 확인후 
    var DELCNT = dts_detail.getCellData(dts_detail.rowpositon, "DELCNT");
    if (eval(DELCNT) > 0) {
        // 삭제 메시지 확인 ... 확인되면 -> 삭제승인 화면이동 ,null,null, 아니면 바로 삭제 
        fn_alertRequiredDelByWeb();
    } else {
        // 관리 삭제로직 
        // 삭제팝업호출 
        //삭제사유 전달받을 input박스 정의한다.
        var rtn = fn_alertDelConfirm();
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            ins_popupOpen(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "170");
        }
        //ins_remove() 함수를 자동호출 하므로 삭제 함수를 만들어 두어야 한다.

    }
};
scwin.btn_prcnm_onclick = function() {
    if (txb_STD_CD.getValue() == "") return;
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드 
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};
